-- BullPen Academy — course: "Valuation: Cheap or Expensive?" (intermediate, Pro)
-- Hand-authored + Zod-validated (scripts/_author_phase2.ts). Re-runnable: ON CONFLICT DO NOTHING.

INSERT INTO academy_courses (slug, title, description, icon, color, order_index, difficulty, requires_pro, is_published) VALUES
  ('valuation', 'Valuation: Cheap or Expensive?', 'A $500 stock can be cheaper than a $20 one. Learn the multiples — P/E, P/S, P/B, EV/EBITDA — that tell you whether a stock is actually a bargain, and how to spot a value trap.', 'Scale', 'blue', 8, 'intermediate', TRUE, TRUE)
ON CONFLICT (slug) DO NOTHING;

INSERT INTO academy_lessons (course_id, slug, title, type, order_index, xp_reward, content)
SELECT
  (SELECT id FROM academy_courses WHERE slug = 'valuation'),
  v.slug, v.title, v.type, v.order_index, v.xp_reward, v.content
FROM (VALUES
  ('price-is-not-value', 'Price ≠ Value', 'read', 0, 10, '{"sections":[{"text":"Here''s a question that trips up almost every new investor: is a $500 stock more expensive than a $20 stock? The honest answer is — you can''t tell. Share price on its own says almost nothing about whether a stock is cheap or dear, because price is quoted per share, and different companies carve themselves into wildly different numbers of shares.","highlightedTerms":[]},{"text":"What actually matters is what you get for that price: the company''s profits, its sales, the assets it owns. To judge that, investors compare the price to those fundamentals using a valuation multiple — a simple ratio that puts the price in context instead of leaving it as a number with no meaning.","highlightedTerms":[{"term":"Valuation Multiple","definition":"A ratio that compares a stock’s price to a fundamental like earnings, sales, or assets — so you can judge whether the price is fair rather than just high or low."}]},{"text":"The starting point for size is Market Cap — the share price multiplied by every share that exists. That $500 stock might have far fewer shares than the $20 one, making it the smaller company overall. Market cap, not share price, tells you how big a business really is.","highlightedTerms":[{"term":"Market Cap","definition":"Total value of all shares combined. Larger = bigger company. \"Large-cap\" usually means over $10 billion."}]},{"text":"The rest of this course is the toolkit for answering “am I paying a fair price?” Each multiple — P/E, P/S, P/B, EV/EBITDA — attacks that question from a different angle, and knowing which to reach for is what separates guessing from valuing.","highlightedTerms":[]}],"funFact":"A stock split changes the share price but not the company’s value. A 2-for-1 split halves the price and doubles the shares — the market cap, and everything you actually own, stays exactly the same."}'::jsonb),
  ('pe-in-depth', 'The P/E Ratio in Depth', 'read', 1, 10, '{"sections":[{"text":"The most-quoted valuation multiple by far is the P/E (TTM) ratio — the share price divided by earnings per share. Read it as a plain-English sentence: how many dollars am I paying for each $1 of the company’s annual profit? A P/E of 20 means $20 of price for every $1 of yearly earnings.","highlightedTerms":[{"term":"P/E (TTM)","definition":"How much investors pay per $1 of profit the company earned in the past 12 months. Lower often signals better value — but context matters."}]},{"text":"There are two flavours. Trailing P/E uses the last twelve months of actual, reported earnings. Forward P/E uses analysts’ estimate of the next twelve months instead. When a company is expected to grow, its Forward P/E is lower than its trailing one — because you’re dividing today’s price by bigger future earnings.","highlightedTerms":[{"term":"Forward P/E","definition":"Like P/E but uses analyst estimates for future earnings. Useful for fast-growing companies where future profits matter more than past ones."}]},{"text":"So what makes one company command a P/E of 40 and another just 10? Mostly growth expectations. Investors happily pay more per dollar of today’s earnings when they believe those earnings will climb fast. A P/E of 40 isn’t “expensive” if profits are on track to double — you’re buying tomorrow’s bigger company.","highlightedTerms":[{"term":"Growth Expectations","definition":"What investors are betting a company’s future earnings will do. Faster expected growth justifies paying a higher P/E today."}]},{"text":"The trap is thinking there’s one “good” P/E. There isn’t. A steady utility at a P/E of 14 and a fast-growing software firm at 38 can both be perfectly fair. Always compare a P/E to the company’s own growth rate and to its industry peers — never in a vacuum.","highlightedTerms":[{"term":"Peer Comparison","definition":"Judging a company’s valuation against similar companies in the same industry, since a “normal” multiple varies widely by sector and growth rate."}]}],"funFact":"When a company loses money, its P/E can’t be calculated at all — you’d be dividing by negative or zero earnings. That’s why unprofitable growth companies are valued on sales instead."}'::jsonb),
  ('beyond-pe', 'Beyond P/E: P/S, P/B & EV/EBITDA', 'read', 2, 10, '{"sections":[{"text":"P/E has a blind spot: a company with no profits has no “E,” so the ratio breaks. Plenty of young, fast-growing firms reinvest everything and report no earnings yet. For them, reach for Price-to-Sales (P/S) — the price compared to revenue per share. Every company has sales, even before it has profit.","highlightedTerms":[{"term":"Price-to-Sales (P/S)","definition":"Share price divided by revenue per share. Useful for valuing companies that have sales but little or no profit yet."}]},{"text":"For asset-heavy businesses like banks and insurers, P/B earns its keep. It compares the price to book value — what the company would be worth if it sold every asset and paid off every debt. A P/B near 1 means you’re paying roughly what the assets are worth on paper.","highlightedTerms":[{"term":"P/B","definition":"Compares stock price to what the company''s assets are worth on paper. Below 1 can indicate the stock is undervalued — or that something is wrong."}]},{"text":"Want to fold growth into the P/E? The PEG ratio divides the P/E by the earnings growth rate. A high P/E paired with fast growth can be more reasonable than a low P/E with none — and a PEG near 1 is a rough shorthand for “fairly priced for its growth.”","highlightedTerms":[{"term":"PEG Ratio","definition":"The P/E ratio divided by the earnings growth rate. It puts a high P/E in context — a PEG around 1 is often considered reasonably priced for the growth on offer."}]},{"text":"Finally, EV/EBITDA is the multiple professionals lean on to compare businesses with different debt loads. It stacks enterprise value (market cap plus debt, minus cash) against core operating profit — so two companies are judged on the business itself, not on how each happens to be financed.","highlightedTerms":[{"term":"EV/EBITDA","definition":"Compares the total company price tag to its operating profit before taxes and non-cash costs. Used to compare companies across industries."}]}],"funFact":"No single multiple wins. Professional analysts almost always look at several at once — a stock that looks cheap on P/E but expensive on EV/EBITDA is often hiding a pile of debt."}'::jsonb),
  ('valuation-quiz', 'Quick Check: Valuation Multiples', 'quiz', 3, 20, '{"questions":[{"question":"Stock A trades at $500 and Stock B at $20. Which is the “cheaper” stock?","options":["Stock B, because $20 is a smaller number","Stock A, because a higher price means more value","You can’t tell from price alone — you need a valuation multiple","They’re equally priced once you round"],"correctIndex":2,"explanation":"Share price is per-share and companies have different share counts, so price alone tells you nothing about value. You need a multiple like P/E to compare them fairly."},{"question":"A stock trades at $60 and earned $3 per share over the last year. What is its trailing P/E?","options":["3","20","180","0.05"],"correctIndex":1,"explanation":"P/E is price divided by earnings per share: $60 ÷ $3 = 20. You’re paying $20 for every $1 of the company’s annual profit."},{"question":"A young company is growing sales fast but has no profits yet. Which multiple is most useful for valuing it?","options":["P/E, because every company has one","Price-to-Sales (P/S), because it uses revenue instead of profit","Dividend yield","None — you can’t value it at all"],"correctIndex":1,"explanation":"With no earnings, P/E can’t be calculated. P/S compares price to revenue, which the company does have — the standard tool for pre-profit growth stocks."},{"question":"A company’s forward P/E is noticeably lower than its trailing P/E. What does that usually imply?","options":["The stock is about to be delisted","Earnings are expected to grow over the next year","The company pays a large dividend","The share price is about to fall"],"correctIndex":1,"explanation":"Forward P/E divides today’s price by expected future earnings. If it’s lower than trailing P/E, the market expects those earnings to rise."}]}'::jsonb),
  ('valuation-match', 'Match the Valuation Metrics', 'match', 4, 15, '{"pairs":[{"term":"P/E (TTM)","definition":"Price divided by the last 12 months of earnings per share."},{"term":"Forward P/E","definition":"Price divided by expected earnings for the next 12 months."},{"term":"Price-to-Sales","definition":"Price compared to revenue — useful when a company has no profit yet."},{"term":"P/B","definition":"Price compared to the company’s net assets, or book value."},{"term":"EV/EBITDA","definition":"Company value including debt, set against core operating profit."}]}'::jsonb),
  ('find-undervalued-demo', 'Find Undervalued Stocks', 'demo', 5, 25, '{"surface":"screener","scope":"sp500","steps":[{"id":"intro","target":"screener-filters","title":"The real screener","body":"This is BullPen’s actual stock screener, running on the whole S&P 500. You just learned the multiples — now use them to surface companies that actually look cheap.","requiredAction":"none"},{"id":"filter","target":"screener-filters","title":"Set a max P/E","body":"In the Valuation section, set a maximum P/E — try 15 — to keep only companies priced modestly against their earnings. Add a sector or P/B filter to narrow further if you like.","requiredAction":"apply-valuation-filter"},{"id":"results","target":"screener-results","title":"Your value shortlist","body":"These are the matches: companies that pass your filter, each one a click away from its full page. This is exactly how a value investor turns 500 stocks into a short list of candidates.","requiredAction":"none"},{"id":"wrap","target":"none","title":"A shortlist, not a verdict","body":"A low multiple is where research begins, not where it ends — the next lesson shows why. But you can now surface value candidates from the entire index in seconds.","requiredAction":"none"}]}'::jsonb),
  ('cheap-or-value-trap', 'Cheap, or a Value Trap?', 'scenario', 6, 25, '{"setup":"I’ve found a stock trading at a P/E of just 7 — while the rest of its industry averages around 18. On the screen it looks like a screaming bargain. But when I dig in: revenue has fallen three years running, the whole industry is shrinking as customers move on, and last month management cut their profit outlook again. Is this a bargain, or a trap?","choices":[{"label":"A P/E of 7 is far below the industry’s 18 — it’s obviously undervalued. Buy it.","feedback":"The low number is tempting, but ask why it’s low. When earnings are shrinking, a low P/E often means the market expects them to keep shrinking — the price is cheap because the business is deteriorating. That’s a classic value trap, and it can get cheaper still.","isCorrect":false},{"label":"The low P/E reflects real trouble — falling sales, a shrinking industry, a cut outlook. It may be cheap for a reason.","feedback":"Exactly right. You didn’t stop at the number — you asked why it’s cheap. A low multiple sitting on top of a declining business is usually a warning, not a gift. True value is a good business at a fair price, not just a small ratio.","isCorrect":true},{"label":"Multiples don’t matter here — I’d just look at whether the share price itself is low.","feedback":"Share price alone can’t tell you value — that was the very first lesson. The P/E is actually doing useful work here by flagging the cheapness; the skill is pairing that signal with the story behind it.","isCorrect":false}]}'::jsonb)
) AS v(slug, title, type, order_index, xp_reward, content)
ON CONFLICT (course_id, slug) DO NOTHING;
